--- /dev/null
+++ build/field-defaults-test/FieldDefaultsRegression.java
@@ -0,0 +1,21 @@
+import java.io.File;
+import lombok.DirectoryRunner;
+import lombok.RunTestsViaDelombok;
+import lombok.transform.TestWithDelombok;
+
+public class FieldDefaultsRegression {
+	public static void main(String[] args) throws Throwable {
+		DirectoryRunner.TestParams params = new TestWithDelombok();
+		int failures = 0;
+		for (String name : args) {
+			try {
+				new RunTestsViaDelombok().createTester(params, new File(params.getBeforeDirectory(), name), "javac", 17).runTest();
+				System.out.println("PASS " + name);
+			} catch (AssertionError error) {
+				System.out.println("FAIL " + name + ": " + error.getMessage());
+				failures++;
+			}
+		}
+		if (failures != 0) throw new AssertionError(failures + " tests failed");
+	}
+}
